function hurtEnemy(e,damage){if(!game.enemies.includes(e))return;e.hp-=damage;e.hit=.12;addBurst(e.x,e.y,e.boss?'#ff5362':'#ffd087',4);if(e.hp<=0){game.enemies.splice(game.enemies.indexOf(e),1);const p=game.player;p.kills++;p.xp+=e.boss?150:28;addBurst(e.x,e.y,'#ffb764',18);game.drops.push({x:e.x,y:e.y,bob:rand(0,TAU)});if(Math.random()<.09||e.boss)spawnEnemyEssence(e.x,e.y);toast(e.boss?'✦ RIFT GUARDIAN SLAIN ✦':'+28 EXPERIENCE');levelCheck();if(e.boss){game.rift.guardianDown=true;toast('THE GUARDIAN FALLS — SEAL THE RIFT')}}}

function openEssenceChoice(item){essenceChoice=item;document.exitPointerLock?.();const meta=item.essence||essenceTypes.find(t=>t.name===item.name)||essenceTypes[0];document.getElementById('essenceTitle').textContent=item.name;document.getElementById('essenceLore').textContent=meta.lore||'A fragment of Astral power waits for a choice.';const choices=document.getElementById('essenceChoices');choices.innerHTML='';const offered=skillPool.filter(s=>!game.player.skills.includes(s.id));for(let i=0;i<3&&i<offered.length;i++){const candidates=offered.splice(Math.floor(Math.random()*offered.length),1)[0];const btn=document.createElement('button');btn.className='btn';btn.innerHTML=`<b>${candidates.icon} ${candidates.name}</b><small>${candidates.desc}</small>`;btn.onclick=()=>absorbEssence(item,candidates);choices.appendChild(btn)}document.getElementById('essenceScreen').classList.remove('hide');document.getElementById('interact').style.display='none'}

function absorbEssence(item,skill){const p=game.player;if(!item.collected)item.collected=true;p.essence++;p.skills.push(skill.id);game.story.firstEssence=true;if(skill.id==='nova'||item.name.includes('Azure'))p.nova=true;if(skill.id==='pulse'){p.hp=Math.min(p.maxHp,p.hp+30);p.mp=Math.min(p.maxMp,p.mp+20)}if(skill.id==='hunt')p.damage+=4;addBurst(item.x,item.y,skill.icon==='➶'?'#9d7cff':'#63f0d3',24);essenceChoice=null;document.getElementById('essenceScreen').classList.add('hide');toast(`${skill.name.toUpperCase()} IMPRINTED • ESSENCE ABSORBED`);updateHUD()}

function leaveEssence(){essenceChoice=null;document.getElementById('essenceScreen').classList.add('hide');document.exitPointerLock?.();toast('ESSENCE LEFT UNTOUCHED')}

function collectAwakeningStone(item){item.collected=true;game.player.awakening=true;game.player.blink=true;game.story.stone=true;addBurst(item.x,item.y,'#aa83ff',16);toast('AWAKENING STONE FOUND • BLINK AWAKENED')}

function interactNearby(){if(!game?.running||essenceChoice)return;let nearby=game.collectibles.find(c=>!c.collected&&dist(game.player,c)<.75);if(nearby){if(nearby.type==='essence')openEssenceChoice(nearby);else collectAwakeningStone(nearby);return true}return false}

function findOpenTile(){let tries=0,x,y;do{x=rand(3,17);y=rand(2,16);tries++}while(tries<100&&(!openPos(x,y)||dist(game.player,{x,y})<3));return tries<100?{x,y}:null}

function spawnRandomEssence(){const pos=findOpenTile();if(!pos)return;const essence=essenceTypes[Math.floor(Math.random()*essenceTypes.length)];game.collectibles.push({...pos,type:'essence',essence,name:essence.name,source:'random',collected:false});toast('AN ESSENCE SHARD HAS APPEARED')}

function spawnEnemyEssence(x,y){const essence=essenceTypes[Math.floor(Math.random()*essenceTypes.length)];game.collectibles.push({x,y,type:'essence',essence,name:essence.name,source:'enemy-loot',collected:false})}

function spawnQuestEssence(){if(!game.essenceQuestPending)return;game.essenceQuestPending=false;const pos=findOpenTile();if(!pos)return;const essence=essenceTypes[Math.floor(Math.random()*essenceTypes.length)];game.collectibles.push({...pos,type:'essence',essence,name:essence.name,source:'quest',collected:false});toast('QUEST REWARD • ESSENCE SHARD DISCOVERED')}

