:root {
--gold:#edc879;--ember:#ff8a50;--teal:#70e0c3;--ink:#090b12;--panel:rgba(12,15,23,.92)}

* {
box-sizing:border-box}
html,body {
height:100%;margin:0;background:#080a10;color:#eee;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;overflow:hidden}
body {
display:grid;place-items:center}
.game-shell {
position:relative;width:min(100vw,160vh);height:min(100vh,62.5vw);min-height:320px;overflow:hidden;background:#10121a;box-shadow:0 20px 100px #000b;border:1px solid #ffffff12}
canvas {
display:block;width:100%;height:100%;image-rendering:pixelated;cursor:crosshair}
.grain {
pointer-events:none;position:absolute;inset:0;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");mix-blend-mode:soft-light}
.hud {
position:absolute;inset:0;pointer-events:none;text-shadow:0 2px 6px #000}
.topbar {
position:absolute;top:18px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:flex-start}
.brand {
font-family:Georgia,serif;letter-spacing:.18em;color:#e8d6b7;text-transform:uppercase;font-size:12px}
.objective {
position:absolute;top:18px;left:50%;transform:translateX(-50%);text-align:center}
.objective b {
display:block;color:var(--gold);font:13px Georgia,serif;letter-spacing:.15em;text-transform:uppercase}
.objective span {
font-size:10px;color:#c4c0bc;letter-spacing:.12em}
.minimap {
width:102px;height:102px;border:1px solid #c8a56270;border-radius:50%;background:#090b11bd;margin-top:8px;overflow:hidden}
.minimap canvas {
width:100%;height:100%;image-rendering:auto}
.player-stats {
position:absolute;left:24px;bottom:20px;width:min(310px,36vw)}
.stat-line {
display:flex;justify-content:space-between;color:#ddd;font-size:11px;letter-spacing:.08em;margin-bottom:5px}
.bar {
height:8px;background:#07080b;border:1px solid #ffffff22}
.fill {
height:100%;background:linear-gradient(90deg,#a83238,#ee6957);transition:width .2s}
.mana .fill {
background:linear-gradient(90deg,#3d7fa0,#70e0c3)}
.level-label {
margin-top:8px;font-size:9px;color:#cfc7b4;letter-spacing:.13em}
