.dialogue-actions {
display:flex;gap:6px;flex-wrap:wrap}
.dialogue-actions button {
border:1px solid #b7a16c55;background:#171a20;color:#dcd1bb;padding:7px 9px;font-size:10px;cursor:pointer}
.damage-vignette {
