 .objective span{display:none}
 .wave{font-size:10px}
 .player-stats{left:12px;bottom:calc(118px + env(safe-area-inset-bottom));width:145px}
 .stat-line{font-size:10px}
 .level-label{font-size:8px}
 .hotbar{display:none}
 .touch-controls{inset:auto 12px calc(14px + env(safe-area-inset-bottom));display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none;touch-action:none}
 .touch-group{grid-template-columns:repeat(3,48px);grid-template-rows:repeat(2,48px);gap:5px}
 .touch-btn{width:48px;height:48px;min-width:48px;min-height:48px;touch-action:none;user-select:none;-webkit-user-select:none}
 .touch-group:last-child{gap:8px}
 .dialogue{bottom:calc(145px + env(safe-area-inset-bottom));max-height:42dvh;overflow:auto;padding:14px}
 .dialogue-actions button{min-height:40px;padding:9px 12px;font-size:12px}
 .inventory{padding:env(safe-area-inset-top) 0 env(safe-area-inset-bottom)}
 .inv-card{max-height:calc(100dvh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom));padding:20px}
 .close{width:40px;height:40px;font-size:22px}
 .card{max-height:calc(100dvh - 24px);overflow:auto;padding:24px 20px}
 .card h1{font-size:32px}
 .card .hint{line-height:1.7}
}
@media(max-width:380px){
 .minimap{width:56px;height:56px}
 .brand{font-size:8px}
 .objective b{font-size:9px}
 .touch-controls{left:8px;right:8px}
 .touch-group{grid-template-columns:repeat(3,44px);grid-template-rows:repeat(2,44px)}
 .touch-btn{width:44px;height:44px;min-width:44px;min-height:44px}
}
</style>

