ebrow{color:var(--gold);font-size:9px;letter-spacing:.22em;text-transform:uppercase}.lore{font:italic 16px Georgia,serif!important}.btn{border:1px solid #d1b47688;background:#18191d;color:#eddeb9;padding:12px 18px;font:11px Georgia,serif;letter-spacing:.12em;cursor:pointer}.btn:hover{background:#28251f}.hint{margin-top:16px;font-size:9px;color:#92896f;letter-spacing:.08em}.touch-controls{display:none}.inventory{position:absolute;inset:0;z-index:19;display:none;place-items:center;background:#080910aa}.inventory.open{display:grid}.inv-card{width:min(520px,calc(100% - 30px));max-height:85%;overflow:auto;border:1px solid #b7a16c55;background:#11131a;padding:24px}.inv-card h2{font:24px Georgia,serif;color:#e4d2aa}.close{float:right;border:1px solid #aaa4;background:none;color:#ddd;width:28px;height:28px}.item-list{display:grid;gap:7px}.item{border:1px solid #ffffff12;background:#0a0c12;padding:10px;text-align:left}.item b,.item small{display:block}.item small{color:#999;font-size:10px;margin-top:3px}.dialogue{position:absolute;z-index:18;left:50%;bottom:18%;transform:translateX(-50%);width:min(620px,calc(100% - 30px));border:1px solid #b7a16c55;background:#0b0d13ed;padding:16px 18px}.dialogue.hide{display:none}.dialogue h3{font:16px Georgia,serif;color:#e6cf9b;margin:0 0 6px}.dialogue p{font-size:12px;line-height:1.5;margin:0 0 10px}.dialogue-actions{display:flex;gap:6px;flex-wrap:wrap}.dialogue-actions button{border:1px solid #b7a16c55;background:#171a20;color:#dcd1bb;padding:7px 9px;font-size:10px;cursor:pointer}.damage-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 120px #b00016;opacity:0;transition:.12s}@media(max-width:700px){.topbar{top:8px;left:10px;right:10px}.brand{font-size:9px}.objective{top:8px}.objective b{font-size:10px}.objective span{font-size:8px}.minimap{width:68px;height:68px}.player-stats{left:10px;bottom:14px;width:130px}.orb{width:58px;height:58px}.hotbar{bottom:10px;gap:4px}.skill{width:38px;height:38px;font-size:17px}.skill .label{font-size:7px}.touch-controls{display:flex}.card{padding:26px 24px}.card h1{font-size:32px}.touch-controls{position:absolute;inset:auto 8px 78px 8px;display:flex;justify-content:space-between;pointer-events:none}.touch-group{display:grid;grid-template-columns:repeat(3,44px);grid-template-rows:repeat(2,44px);gap:4px;pointer-events:auto}.touch-btn{border:1px solid #c6b48355;border-radius:50%;background:#10131acc;color:#e4d6b6;font-size:14px}.touch-group:last-child{display:flex;align-items:flex-end}.dialogue{bottom:132px}}
