 window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyI')toggleInventory();if(e.code==='Escape')if(dialogueNpc)closeDialogue();else if(invOpen)toggleInventory();if(e.code==='KeyE')interact();if(e.code==='KeyQ')potion();if(e.code==='Space')shoot()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>keys={});
