+for(const el of document.querySelectorAll('[data-move]')){const code={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[el.dataset.move];el.addEventListener('pointerdown',e=>{e.preventDefault();keys[code]=true;try{el.setPointerCapture(e.pointerId)}catch(_){}});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev',()=>{keys[code]=false})}document.getElementById('touchShoot').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});document.getElementById('touchInteract').addEventListener('pointerdown',e=>{e.preventDefault();interact()});let touchLook=null;let touchLookY=0;canvas.addEventListener('touchstart',e=>{if(game?.running&&!invOpen&&!dialogueNpc&&e.touches.length){touchLook=e.touches[0].clientX;touchLookY=e.touches[0].clientY}},{passive:true});canvas.addEventListener('touchmove',e=>{if(touchLook!==null&&game&&e.touches.length){let touch=e.touches[0];let dx=touch.clientX-touchLook;touchLook=touch.clientX;touchLookY=touch.clientY;game.player.a+=dx*.006}},{passive:true});canvas.addEventListener('touchend',()=>{touchLook=null},{passive:true});canvas.addEventListener('touchcancel',()=>{touchLook=null},{passive:true});
 requestAnimationFrame(frame);
